/* ===== Chips (Chips.kt): ButtonChip, ToggleableChip, RemovableChip ===== */
// [height, radius, text style, gap, padding, padding with leading icon, remove padding start (no/with leading), end & vertical, remove icon]
const CHIP = {
  small: [32, 16, 'labelMedium', 2, 16, 12, [16, 12], 6, 20],
  regular: [40, 38, 'labelLarge', 4, 20, 16, [20, 16], 8, 24],
};
class SuiChip extends SuiBase {
  static get css() {
    return `.root{display:flex;align-items:center;min-height:var(--h);border-radius:var(--rad);background:var(--bg);color:var(--fg);overflow:hidden;white-space:nowrap;font:var(--font);
  transition:background-color var(--spring-instant-ms,254ms) var(--spring-instant,ease),color var(--spring-instant-ms,254ms) var(--spring-instant,ease),opacity var(--spring-rapid-ms,387ms) var(--spring-rapid,ease),transform var(--spring-rapid-ms,387ms) var(--spring-rapid,ease)}
.main{display:flex;align-items:center;gap:var(--gap);padding:var(--pt) var(--pe) var(--pb) var(--ps);min-height:var(--h)}
.ico{display:inline-flex}.ico:empty{display:none}
.rm{display:none;height:var(--h);min-width:var(--h);padding:var(--rp) var(--rp) var(--rp) var(--gap);align-items:center;justify-content:center;cursor:pointer}
.rm .x{display:flex;border-radius:50%}
.removable .rm{display:flex}
.hide{opacity:0!important;transform:scale(.95);pointer-events:none}`;
  }
  get kind() { return this.constructor.kind || null; }
  toggle() { return this.kind === 'toggle' || this.bool('toggle'); }
  removable() { return this.kind === 'removable' || this.bool('removable'); }
  clickable() { return this.toggle() || this.removable() || this.attr('clickable') !== 'false'; }
  template() {
    return `<div class="root ind" part="root" role="button" tabindex="0"><div class="main"><slot name="leading"><span class="ico lead"></span></slot><slot><span class="txt"></span></slot><slot name="trailing"><span class="ico trail"></span></slot></div><div class="rm" part="remove" role="button" aria-label="Remove"><span class="x"></span></div></div>`;
  }
  build() {
    const r = this.$('.root');
    r.addEventListener('keydown', e => {
      if (this.clickable() && !this.bool('disabled') && (e.key === 'Enter' || e.key === ' ')) {
        e.preventDefault(); r.click();
      }
    });
    const f = () => { this._lead = this.$('slot[name=leading]').assignedNodes().length > 0; this.sync(); };
    this.$('slot[name=leading]').addEventListener('slotchange', f);
    this.$('.rm').addEventListener('click', (e) => {
      e.stopPropagation(); if (this.bool('disabled')) return;
      const ev = this.emit('remove', {}, true);
      if (!ev.defaultPrevented) this.setAttribute('visible', 'false');
    });
    r.addEventListener('click', () => {
      if (this.bool('disabled') || !this.clickable()) return;
      if (this.toggle()) { const next = !this.bool('selected'); this.toggleAttribute('selected', next); this.emit('checked-change', { selected: next, checked: next }); }
      this.emit('click-action');
    });
  }
  sync() {
    const r = this.$('.root'), k = CHIP[(this.attr('size', 'small') || '').toLowerCase()] || CHIP.small;
    const lead = this._lead || this.hasAttribute('leading-icon'), rm = this.removable(), on = this.toggle() && this.bool('selected');
    this.$('.txt').textContent = this.attr('label', this.attr('text', ''));
    this.$('.lead').innerHTML = iconHtml(this.attr('leading-icon'), 12);
    this.$('.trail').innerHTML = iconHtml(this.attr('trailing-icon'), 12);
    const t = TYPE[k[2]], sx = (n, v) => r.style.setProperty(n, v + 'px');
    sx('--h', k[0]); r.style.setProperty('--rad', k[1] === 16 ? 'var(--radius-large,16px)' : k[1] + 'px'); sx('--gap', k[3]);
    r.style.setProperty('--font', `${t[2]} ${t[0]}px/${t[1]}px var(--font-sans,system-ui,sans-serif)`);
    if (rm) { sx('--ps', k[6][lead ? 1 : 0]); sx('--pe', 0); sx('--pt', k[7]); sx('--pb', k[7]); sx('--rp', k[7]); }
    else { const p = lead ? k[5] : k[4]; sx('--ps', p); sx('--pe', p); sx('--pt', 0); sx('--pb', 0); }
    r.classList.toggle('removable', rm);
    this.$('.x').innerHTML = glyphSvg('chip_remove', k[8], true);
    // ToggleableChip: backgroundColor / contentColor are the inactive state, activeBackgroundColor / activeContentColor the active one
    const bg = this.toggle() ? (on ? (this.attr('active-container-color') || 'var(--r-fill-secondary)') : (this.attr('container-color') || 'var(--r-fill-tertiary)')) : (this.attr('container-color') || 'var(--r-fill-secondary)');
    this.paint(r, bg, (this.toggle() && on ? this.attr('active-content-color') : this.attr('content-color')) || 'var(--r-label-primary)');
    r.classList.toggle('dis', this.bool('disabled'));
    const clickable = this.clickable();
    r.classList.toggle('ind', clickable);
    if (clickable) { r.setAttribute('role', 'button'); r.setAttribute('tabindex', '0'); }
    else { r.removeAttribute('role'); r.removeAttribute('tabindex'); }
    if (this.toggle()) r.setAttribute('aria-pressed', String(on));
    else r.removeAttribute('aria-pressed');
    // RemovableChip `visible`: alpha and scale 0.95 on spring `rapid`, then it leaves the layout
    const vis = this.attr('visible') !== 'false';
    clearTimeout(this._gone);
    if (vis) { this.style.display = ''; requestAnimationFrame(() => r.classList.remove('hide')); }
    else { r.classList.add('hide'); this._gone = setTimeout(() => { this.style.display = 'none'; }, 390); }
  }
}
const CHIP_ATTRS = ['size', 'disabled', 'clickable', 'selected', 'toggle', 'removable', 'visible', 'label', 'text', 'leading-icon', 'trailing-icon', 'container-color', 'content-color', 'active-container-color', 'active-content-color'];
register('sui-chip', SuiChip, CHIP_ATTRS);
class SuiButtonChip extends SuiChip {}
