/* ===== Divider (Divider.kt): 0.5dp, dividerLine = sub-black-12 ===== */
class SuiDivider extends SuiBase {
  static get css() { return ':host{display:block}:host([orientation=vertical]){display:inline-block;align-self:stretch}.l{background:var(--bg)}'; }
  get fixed() { return this.constructor.fixed || null; }
  template() { return '<div class="l" part="root" role="separator"></div>'; }
  sync() {
    const l = this.$('.l'), v = (this.fixed || this.attr('orientation', 'horizontal')) === 'vertical', t = this.num('thickness', 0.5);
    if (this.fixed) this.setAttribute('orientation', this.fixed);
    l.style.setProperty('--bg', this.attr('color') || 'var(--r-divider)');
    l.style.width = v ? t + 'px' : '100%'; l.style.height = v ? '100%' : t + 'px'; l.style.minHeight = v ? '100%' : '';
    l.setAttribute('aria-orientation', v ? 'vertical' : 'horizontal');
  }
}
register('sui-divider', SuiDivider, ['orientation', 'color', 'thickness']);
class SuiHorizontalDivider extends SuiDivider { static get fixed() { return 'horizontal'; } }
class SuiVerticalDivider extends SuiDivider { static get fixed() { return 'vertical'; } }
register('sui-horizontal-divider', SuiHorizontalDivider, ['color', 'thickness']);
register('sui-vertical-divider', SuiVerticalDivider, ['color', 'thickness']);

/* ===== ListItem (ListItem.kt): min 360x60, r16, padding 16/4/16/16, gaps 12 / 16 / 4 ===== */
class SuiListItem extends SuiBase {
  static get css() {
    return `:host{display:block;min-width:360px}
.root{display:flex;align-items:center;min-height:60px;padding:16px 4px 16px 16px;border-radius:var(--radius-large,16px);background:var(--bg);overflow:hidden}
.lead{display:none;align-self:stretch;align-items:center;justify-content:center;padding-right:12px;color:var(--lc,inherit)}
.trail{display:none;align-items:center;justify-content:center;min-width:40px;min-height:40px;padding-left:16px;color:var(--tc,inherit)}
.has-lead .lead,.has-trail .trail{display:flex}
.col{flex:1;min-width:var(--col-min,0)}
.head{${ts('bodyLarge')};color:var(--hc)}
.sup{${ts('bodyMedium')};color:var(--sc);padding-top:4px}
.sup.none{display:none}`;
  }
  template() {
    return `<div class="root" part="root"><div class="lead"><slot name="leading"></slot></div><div class="col"><div class="head"><slot name="headline"><span class="h"></span></slot></div><div class="sup"><slot name="supporting"><span class="s"></span></slot></div></div><div class="trail"><slot name="trailing"></slot></div></div>`;
  }
  build() {
    const r = this.$('.root'), f = () => {
      r.classList.toggle('has-lead', !!this._lead || this.hasAttribute('leading-icon'));
      r.classList.toggle('has-trail', !!this._trail || this.hasAttribute('trailing-icon'));
      const sup = this.$('slot[name=supporting]').assignedNodes().length > 0 || this.hasAttribute('supporting');
      this.$('.sup').classList.toggle('none', !sup);
    };
    this._f = f;
    spatialHoverEffect(r);
    this.$('slot[name=leading]').addEventListener('slotchange', () => { this._lead = this.$('slot[name=leading]').assignedNodes().length > 0; f(); });
    this.$('slot[name=trailing]').addEventListener('slotchange', () => { this._trail = this.$('slot[name=trailing]').assignedNodes().length > 0; f(); });
    this.$('slot[name=supporting]').addEventListener('slotchange', f);
    r.addEventListener('click', () => { if (!this.bool('disabled')) this.emit('click-action'); });
  }
  sync() {
    const r = this.$('.root');
    this.$('.h').textContent = this.attr('headline', ''); this.$('.s').textContent = this.attr('supporting', '');
    if (this.hasAttribute('leading-icon') && !this._lead) this.$('slot[name=leading]').innerHTML = `<span>${iconHtml(this.attr('leading-icon'), 24)}</span>`;
    if (this.hasAttribute('trailing-icon') && !this._trail) this.$('slot[name=trailing]').innerHTML = `<span>${iconHtml(this.attr('trailing-icon'), 24)}</span>`;
    const s = (n, v, d) => r.style.setProperty(n, v || d);
    s('--bg', this.attr('container-color'), 'var(--r-fill-light)'); s('--hc', this.attr('headline-color'), 'var(--r-label-primary)');
    s('--sc', this.attr('supporting-color'), 'var(--r-label-tertiary)');
    this.attr('leading-color') ? r.style.setProperty('--lc', this.attr('leading-color')) : r.style.removeProperty('--lc');
    this.attr('trailing-color') ? r.style.setProperty('--tc', this.attr('trailing-color')) : r.style.removeProperty('--tc');
    r.classList.toggle('dis', this.bool('disabled')); this._f();
  }
}
register('sui-list-item', SuiListItem, ['headline', 'supporting', 'leading-icon', 'trailing-icon', 'disabled', 'container-color', 'leading-color', 'headline-color', 'supporting-color', 'trailing-color']);

/* ===== TextField, TextArea (TextField.kt): 280 wide, min 48 high, r12, border 1 inside for error ===== */
class SuiTextField extends SuiBase {
  static get css() {
    return `:host{display:inline-block;width:var(--w,280px);min-width:280px;vertical-align:top}
.wrap{width:100%}
.field{position:relative;isolation:isolate;display:flex;align-items:var(--va,center);min-width:280px;min-height:48px;border-radius:var(--rad,var(--radius-medium-large,12px));overflow:hidden;background:var(--bg);cursor:text}
.field::before{content:"";position:absolute;inset:0;z-index:-1;background:transparent;pointer-events:none}
@media (hover:hover){.field:not(.focus):hover::before{background:var(--r-lighten-hover)}}
.field:not(.focus):active::before{background:var(--r-lighten-pressed)}
.field.focus{background:var(--fc)}
.field.err::after{content:"";position:absolute;inset:0;border-radius:inherit;box-shadow:inset 0 0 0 1px var(--ec,var(--r-error));pointer-events:none}
.lead{min-width:12px;display:flex;align-items:center;justify-content:center}
.lead.has{padding:0 4px 0 8px}.lw{display:none;min-width:32px;min-height:32px;align-items:center;justify-content:center}.lead.has .lw{display:flex}
.body{flex:1;min-width:0;padding:12px 0;display:flex;align-items:center}
.in{width:100%;border:0;outline:0;background:transparent;padding:0;margin:0;color:var(--tx);${ts('bodyLarge')};height:20px;resize:none;overflow:hidden;display:block}
.in::placeholder{color:var(--ph);opacity:1}
.field.focus .in::placeholder{opacity:.3}
.tail{display:flex;align-items:center;justify-content:center}
.tail.slot{padding:4px;min-width:48px;min-height:48px}
.tail.clr{width:56px;padding:0 4px 0 12px;height:48px}
.tail.sp{width:12px}
.cb{display:none;width:40px;height:40px;border-radius:50%;align-items:center;justify-content:center;overflow:hidden}
.field.focus.filled .tail.clr .cb{display:flex}
.sup{display:none;padding-top:4px;${ts('bodySmall')};color:var(--sc)}
.sup.on{display:block}`;
  }
  get multi() { return this.constructor.multi || this.bool('multiline'); }
  template() {
    return `<div class="wrap"><div class="field" part="field"><div class="lead"><div class="lw"><slot name="leading"></slot></div></div><div class="body"></div><div class="tail sp"><slot name="trailing"></slot><span class="cb ind" role="button" aria-label="clear"></span></div></div><div class="sup" part="supporting"><slot name="supporting"></slot><span class="st"></span></div></div>`;
  }
  build() {
    const multi = this.multi, body = this.$('.body');
    body.innerHTML = multi ? '<textarea class="in" rows="1"></textarea>' : '<input class="in" type="text">';
    const inp = this._in = this.$('.in'), field = this.$('.field');
    this.$('.cb').innerHTML = glyphSvg('close_circle_fill', 18, false);
    inp.addEventListener('input', () => { this.fit(); this.state(); this.emit('value-change', { value: inp.value }); });
    inp.addEventListener('focus', () => { field.classList.add('focus'); this.state(); });
    inp.addEventListener('blur', () => { field.classList.remove('focus'); this.state(); });
    field.addEventListener('mousedown', (e) => { if (e.target !== inp && !e.target.closest('.cb')) { e.preventDefault(); this._in.focus(); } });
    const cb = this.$('.cb');
    cb.addEventListener('mousedown', (e) => e.preventDefault());
    cb.addEventListener('click', () => { this._in.value = ''; this.fit(); this.state(); this.emit('value-change', { value: '' }); this._in.focus(); });
    const sl = this.$('slot[name=trailing]');
    sl.addEventListener('slotchange', () => { this._tr = sl.assignedNodes().length > 0; this.sync(); });
    const ll = this.$('slot[name=leading]');
    ll.addEventListener('slotchange', () => { this.$('.lead').classList.toggle('has', ll.assignedNodes().length > 0); });
  }
  fit() {
    if (!this.multi) return; const t = this._in; t.style.height = 'auto';
    const max = this.num('max-lines', 0) * 20; t.style.height = (max ? Math.min(t.scrollHeight, max) : t.scrollHeight) + 'px'; t.style.overflowY = max && t.scrollHeight > max ? 'auto' : 'hidden';
  }
  state() { const f = this.$('.field'); f.classList.toggle('filled', this._in.value.length > 0); }
  get value() { return this._in ? this._in.value : this.attr('value', ''); }
  set value(v) { this.setAttribute('value', v); if (this._in) { this._in.value = v; this.state(); this.fit(); } }
  focus() { this._in && this._in.focus(); }
  sync() {
    const inp = this._in, f = this.$('.field'), multi = this.multi;
    if (this.hasAttribute('value') && inp.value !== this.attr('value')) inp.value = this.attr('value');
    inp.placeholder = this.attr('placeholder', ''); inp.disabled = this.bool('disabled'); inp.readOnly = this.bool('readonly');
    if(inp.tagName!==(multi?'TEXTAREA':'INPUT')){const next=document.createElement(multi?'textarea':'input');next.className='in';next.value=inp.value;this.$('.body').replaceChildren(next);this._in=next;next.addEventListener('input',()=>{this.fit();this.state();this.emit('value-change',{value:next.value});});next.addEventListener('focus',()=>f.classList.add('focus'));next.addEventListener('blur',()=>f.classList.remove('focus'));return this.sync();}
    if (multi) inp.rows = this.num('min-lines', 1);
    f.style.setProperty('--bg', this.attr('container-color') || 'var(--r-fill-tertiary)');
    f.style.setProperty('--fc', this.attr('focus-color') || 'var(--r-fill-secondary)');
    f.style.setProperty('--tx', this.attr('text-color') || 'var(--r-label-primary)');
    f.style.setProperty('--ph', this.attr('placeholder-color') || 'var(--r-label-quaternary)');
    f.style.setProperty('--va', multi ? 'flex-start' : 'center');
    this.attr('corner-radius') ? f.style.setProperty('--rad', this.num('corner-radius', 12) + 'px') : f.style.removeProperty('--rad');   // cornerRadius
    f.style.setProperty('--ec', this.attr('error-color') || 'var(--r-error)');
    f.classList.toggle('err', this.bool('error')); f.classList.toggle('dis', this.bool('disabled'));
    const w = this.attr('width'); w ? this.style.setProperty('--w', parseFloat(w) + 'px') : this.style.removeProperty('--w');
    const clearable = !multi && (this.hasAttribute('clearable') ? this.bool('clearable') : true);
    const tail = this.$('.tail'); tail.className = 'tail ' + (this._tr ? 'slot' : clearable ? 'clr' : 'sp');
    this.$('.cb').style.display = '';
    const sup = this.attr('supporting-text', ''); this.$('.st').textContent = sup;
    const s = this.$('.sup'); s.classList.toggle('on', !!sup || !!this.querySelector('[slot=supporting]'));
    s.style.setProperty('--sc', this.attr('supporting-color') || (this.bool('error') ? (this.attr('error-color') || 'var(--r-error)') : 'var(--r-label-tertiary)'));
    this.state(); this.fit();
  }
}
const TF_ATTRS = ['value', 'placeholder', 'disabled', 'readonly', 'multiline', 'width', 'supporting-text', 'clearable', 'error', 'min-lines', 'max-lines', 'container-color', 'text-color', 'placeholder-color', 'focus-color', 'supporting-color', 'error-color', 'corner-radius'];
register('sui-text-field', SuiTextField, TF_ATTRS);
class SuiTextArea extends SuiTextField { static get multi() { return true; } }
register('sui-text-area', SuiTextArea, TF_ATTRS);

