register('sui-coachmark', SuiCoachmark, COACH_ATTRS);
class SuiSimpleCoachmark extends SuiCoachmark { static get variant() { return 'simple'; } }
class SuiRichCoachmark extends SuiCoachmark { static get variant() { return 'rich'; } }
class SuiImageCoachmark extends SuiCoachmark { static get variant() { return 'image'; } }
register('sui-simple-coachmark', SuiSimpleCoachmark, COACH_ATTRS);
register('sui-rich-coachmark', SuiRichCoachmark, COACH_ATTRS);
