const GLASS = 'backdrop-filter:blur(40px) saturate(1.3);-webkit-backdrop-filter:blur(40px) saturate(1.3);box-shadow:0 18px 54px rgba(0,0,0,.2),inset 0 0 0 1px rgba(255,255,255,.3)';

