define('sui-planar-window', SuiPlanarWindow);

/* Preview-only Volume boundary. Numeric attributes are dp; 1dp = 1 CSS px.
   The inset wireframe is schematic, never a native mesh or meter conversion. */
class SuiVolume extends SuiBase {
  static get observedAttributes() { return ['width', 'height', 'depth']; }
  static get css() {
    return `:host{display:block;position:relative;flex:none;box-sizing:border-box;padding:0;isolation:isolate;background:rgba(255,255,255,.16);color:var(--r-label-primary)}
.bounds{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:0;overflow:hidden}
.bounds path{fill:none;stroke:rgba(55,67,80,.3);stroke-width:1;vector-effect:non-scaling-stroke;stroke-dasharray:5 5}
.caption{position:absolute;top:12px;left:16px;pointer-events:none;font:12px/18px system-ui;color:rgba(35,43,52,.7);z-index:2}
.content{position:relative;width:100%;height:100%;z-index:1}slot{display:contents}`;
  }
  template() { return '<svg class="bounds" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M.2 99.8V.2H99.8V99.8Z M6 94V6H94V94Z M.2 .2L6 6 M99.8 .2L94 6 M.2 99.8L6 94 M99.8 99.8L94 94"/></svg><span class="caption"></span><div class="content"><slot></slot></div>'; }
  sync() {
    const values = ['width', 'height', 'depth'].map(k => Number(this.getAttribute(k)));
    const valid = values.every(v => Number.isFinite(v) && v > 0);
    for (const [i, axis] of ['width', 'height'].entries()) {
      if (Number.isFinite(values[i]) && values[i] > 0) this.style[axis] = values[i] + 'px';
      else this.style.removeProperty(axis);
    }
    this.$('.caption').textContent = valid ? `Volume · ${values.join(' × ')} dp · schematic bounds`
      : 'Volume · set positive width, height and depth (dp)';
  }
}
define('sui-volume', SuiVolume);

